    'system.globalSettings.keyDescriptions.asynq.core_concurrency': 'Guaranteed per-process concurrency for document and manual parsing. Core may also borrow the shared elastic pool. Minimum 1; requires a service restart.',
    'system.globalSettings.keyDescriptions.asynq.enrichment_concurrency': 'Guaranteed per-process concurrency for summaries, images, graph, and question generation. Enrichment may also borrow the shared elastic pool. Minimum 1; requires a service restart.',
